#!/usr/bin/env python3
"""Build a self-contained, fictional-data Persian owner booklet (no network)."""
from pathlib import Path
import base64

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1]
def data(path, mime):
    return 'data:' + mime + ';base64,' + base64.b64encode(path.read_bytes()).decode()
font_fa = data(ROOT/'apps/lifemate/assets/fonts/LifeGuidePersian.ttf', 'font/ttf')
font_en = data(ROOT/'apps/lifemate/assets/fonts/LifeGuideLatin.ttf', 'font/ttf')
screenshot = data(ROOT/'docs/audits/evidence/personal-user-first-launch-2026-10-20.png', 'image/png')
def badge(text, style='future'):
    return f'<span class="badge {style}">{text}</span>'
def note(title, text, style=''):
    return f'<div class="note {style}"><strong>{title}</strong><p>{text}</p></div>'
def cards(items):
    return '<div class="cards">'+''.join(f'<div class="card"><span class="card-number">{i+1:02}</span><h3>{t}</h3><p>{v}</p></div>' for i,(t,v) in enumerate(items))+'</div>'
def diagram(kind):
    # Original geometric illustration; no external artwork or identifiable people.
    person='<circle cx="0" cy="0" r="24" fill="#d8ae88"/><path d="M-25 -4 Q-28 -34 0 -30 Q30 -29 25 -4 L16 -14 L-10 -11Z" fill="#35324a"/><path d="M-43 91 L-35 40 Q0 19 35 40 L43 91Z" fill="currentColor"/>'
    if kind=='vision':
        return f'<div class="illustration hero-art"><svg viewBox="0 0 660 290" role="img" aria-label="تصویر نمادین زندگی، یادگیری و همراهی خانواده"><rect x="8" y="12" width="644" height="265" rx="34" fill="#eee8f6"/><circle cx="330" cy="145" r="101" fill="#fffaf2"/><path d="M190 205 Q330 20 470 205" fill="none" stroke="#b4c9c0" stroke-width="4" stroke-dasharray="8 9"/><g transform="translate(259 140)" color="#6c5995">{person}</g><g transform="translate(398 140)" color="#3e796f">{person}</g><rect x="280" y="187" width="100" height="65" rx="12" fill="#d8ad71"/><path d="M330 196V243M291 200Q310 195 324 204M336 204Q351 194 369 200" stroke="#fffaf2" stroke-width="3" fill="none"/><circle cx="126" cy="83" r="29" fill="#dceae3"/><path d="M113 83l9 9 18-20" stroke="#3e796f" stroke-width="5" fill="none"/><circle cx="536" cy="83" r="29" fill="#f0dcc6"/><path d="M521 83h30M536 68v30" stroke="#9a6b3f" stroke-width="4"/><circle cx="134" cy="220" r="18" fill="#d6c9e8"/><circle cx="526" cy="220" r="18" fill="#d6c9e8"/></svg></div>'
    if kind=='lesson':
        return '<div class="illustration lesson-art"><div class="book"><span class="eyebrow">نمونهٔ تألیفی · ریاضی هفتم</span><h3>عدد منفی، حرکت در یک جهت</h3><div class="numberline" dir="ltr">−۵　−۴　−۳　−۲　−۱　۰　۱　۲　۳</div><div class="math" dir="ltr">−۲ + ۵ = ۳</div><p>از منفی دو، پنج گام به راست: به سه می‌رسیم.</p></div><div class="timer"><b dir="ltr">25 / 5</b><span>تمرکز / استراحت</span></div></div>'
    if kind=='video':
        return '<div class="illustration video-art"><div class="video-frame"><span class="play-icon" aria-hidden="true">▷</span><h3>جای ویدئوی اختیاری</h3><p>تصویر طراحی است؛ پخش زنده ندارد.</p></div><div class="video-back">تمام‌صفحه ← بازگشت به همان درس</div></div>'
    if kind=='family':
        return f'<div class="illustration family-art"><svg viewBox="0 0 660 190" role="img" aria-label="سه حساب مستقل با مرز مجوز"><rect x="14" y="12" width="632" height="164" rx="28" fill="#eee8f6"/><path d="M160 110H500" stroke="#b2aaa0" stroke-width="3" stroke-dasharray="7 8"/><g transform="translate(130 66) scale(.72)" color="#3e796f">{person}</g><g transform="translate(330 66) scale(.72)" color="#6c5995">{person}</g><g transform="translate(530 66) scale(.72)" color="#a46f49">{person}</g><circle cx="230" cy="110" r="20" fill="#fffaf2"/><path d="M224 106v-6a6 6 0 0112 0v6M222 106h16v14h-16z" fill="none" stroke="#6c5995" stroke-width="2"/><circle cx="430" cy="110" r="20" fill="#fffaf2"/><path d="M424 106v-6a6 6 0 0112 0v6M422 106h16v14h-16z" fill="none" stroke="#6c5995" stroke-width="2"/></svg><div class="underlabels"><span>والد مجاز</span><span>فرزند</span><span>والد مجاز</span></div></div>'
    if kind=='journey':
        return '<div class="illustration journey"><div>یک گوشی<br><b>قابل اتکا</b></div><span>←</span><div>سه دستگاه<br><b>با مجوز روشن</b></div><span>←</span><div>یک درس<br><b>کامل و بازبینی‌شده</b></div></div>'
    if kind=='flow':
        return '<div class="illustration feedback-flow">'+''.join(f'<div><b>{n}</b><span>{t}</span></div>' for n,t in [('۱','انتخاب با رضایت'),('۲','دسته‌بندی مسئله'),('۳','بازبینی انسانی'),('۴','نسخهٔ آزموده')])+'</div>'
    return '<div class="illustration life-art">'+''.join(f'<div><span>{s}</span><h3>{t}</h3><p>{p}</p></div>' for s,t,p in [('◯','عادت‌های کوچک','خواب، حرکت و نظم روزمره'),('◇','گفت‌وگوی خانواده','توافق روشن و کار مشترک'),('△','مهارت زندگی','تصمیم‌گیری و مسئولیت‌پذیری')])+'</div>'

pages=[]
def page(n, title, subtitle, body, label='پیشنهاد آینده'):
    pages.append(f'<article class="page" id="p{n}" aria-labelledby="title{n}"><header><span>LifeGuide / لایف‌گاید</span><span>راهنمای مالک · نسخهٔ ۱</span></header><div class="page-content"><div class="kicker">{n:02} / {label}</div><h1 id="title{n}">{title}</h1><p class="subtitle">{subtitle}</p>{body}</div><footer><span>۲۱ اکتبر ۲۰۲۶ · همهٔ مثال‌ها ساختگی‌اند</span><span dir="ltr">{n:02} / 12</span></footer></article>')

page(1,'همراهی برای زندگی؛<br>از یک روز خوب شروع می‌شود.','تصویر روشن مقصد، واقعیت امروز و مسیر کوتاه‌تر برای تحویل.',diagram('vision')+cards([('من','برنامهٔ روزانه، انتخاب‌های کوچک و حس پیشرفت؛ برای هر سن و هر مرحلهٔ زندگی.'),('خانواده','حساب مستقل، همکاری با رضایت و دیدپذیری روشن؛ بدون حذف حریم شخصی.'),('یادگیری','یک مسیر کامل برای فهمیدن، تمرین و مرور؛ فراتر از فهرست ویدئوها.')])+note('چگونه این دفترچه را بخوانیم؟','«واقعی امروز» فقط به بستهٔ شخصیِ ثبت‌شده اشاره دارد. تصویرهای دیگر نمونهٔ مفهومی و امکانات آینده‌اند؛ تأیید این دفترچه مجوز انتشار، تغییر حریم خصوصی یا فعال‌سازی AI نیست.'),'چشم‌انداز و راه خواندن')

page(2,'امروز واقعاً چه داریم؟','لایف‌گاید شخصی Android؛ بستهٔ اولیه برای آزمون یک گوشی.',badge('واقعی امروز · شواهد ثبت‌شده','verified')+'<div class="actual-layout"><figure class="actual-shot"><img class="actual" src="'+screenshot+'" alt="تصویر واقعی نخستین اجرای APK شخصی در شبیه‌ساز؛ فیلدها خالی هستند"><figcaption>تصویر واقعی شبیه‌ساز API35، نه گوشی فیزیکی</figcaption></figure><div><h2>بدون URL، API و ورود</h2><p>نسخهٔ <b dir="ltr">0.7.2-personal.1 / code9</b>، داده را در SQLite خصوصی همین گوشی نگه می‌دارد.</p><ul><li>برنامهٔ یک‌باره، روزانه، روزدرمیان یا هفتگی؛ ساعت مستقل برای روزها.</li><li>تیک، ویرایش و بایگانی هر نوبت؛ نام دلخواه، نام همراه و چهار تم.</li><li>یادآوری فقط با انتخاب کاربر و مجوز Android؛ متن اعلان عمومی است.</li></ul><p class="small">روزهای هفته فارسی‌اند؛ تاریخ فعلی میلادی است. شناسهٔ بسته: <b dir="ltr">ir.lifeguide.app.device</b></p></div></div>'+note('حد واقعی این تحویل','این APK آزمایشی debug است. خانواده، همگام‌سازی، خروجی، backup و بازیابی ندارد. حذف برنامه یا داده می‌تواند برنامه‌ها را از بین ببرد؛ برای اختلاف امضا، هیچ داده‌ای پاک نشود.','warning')+'<p class="small source">سند مبنا: PROJECT_STATE، بخش ۲۰ اکتبر؛ کد 3e36dfd. گوشی واقعی و ارتقای بدون حذف داده هنوز بررسی نشده‌اند.</p>','واقعی امروز')

page(3,'اول، یک هفتهٔ قابل اعتماد','برای استفادهٔ شخصی کودک، سادگی و حفظ داده از افزودن منو مهم‌تر است.',badge('نمونهٔ پیشنهادی · در APK تصویر نشده')+'<div class="illustration week-art"><div class="week-head"><b>هفتهٔ من</b><span>دادهٔ ساختگی</span></div>'+''.join(f'<div class="week-row"><b>{d}</b><span>{t}</span><i>{v}</i></div>' for d,t,v in [('شنبه','مرور ریاضی · ۱۷:۰۰','انجام شد'),('دوشنبه','پیاده‌روی · ۱۸:۳۰','در پیش'),('چهارشنبه','تمرین زبان · ۱۶:۰۰','در پیش')])+'</div>'+cards([('امروز و هفته','کار روشن، ساعت هر روز و یک تیک مستقل؛ ویرایش یک نوبت، بقیهٔ هفته را خراب نکند.'),('یادآوری قابل فهم','روشن و خاموش‌کردن آشکار، مجوز سیستم و توضیح محدودیت باتری؛ آزمون روی گوشی واقعی.'),('داده امن بماند','اولویت بعدی: خروجی و بازیابی آزموده، ارتقا با حفظ داده و کلید؛ بهبود جلالی، کاری کوچک و مستقل است.')])+note('معیار پایان بستهٔ نزدیک','ثبت دو روز با ساعت متفاوت، تیک/ویرایش/بایگانی، بستن و بازکردن، خاموشی و لغو یادآوری و بازیابی خروجی باید روی دادهٔ ساختگی نتیجهٔ قابل مشاهده داشته باشد.'),'اولویت نزدیک')

page(4,'یک درس کامل، از هدف تا مرور','نمونهٔ تألیفی پیشنهادی برای ریاضی پایهٔ هفتم؛ هنوز نصب و منتشر نشده است.',diagram('lesson')+'<div class="steps"><div><b>۱ · هدف و توضیح</b><p>جمع اعداد صحیح را با جهت حرکت روی محور توضیح بده؛ علامت عدد، جهت را مشخص می‌کند.</p></div><div><b>۲ · مثال حل‌شده</b><p>منفی دو به‌علاوهٔ پنج: از <bdi dir="ltr">−۲</bdi> شروع کن، پنج گام به راست برو؛ پاسخ ۳ است.</p></div><div><b>۳ · بازیابی و تمرین</b><p>کتاب را ببند و روش را توضیح بده؛ سپس <bdi dir="ltr">−۳+۲</bdi> و <bdi dir="ltr">۴+(−۶)</bdi> را حل کن.</p></div><div><b>۴ · آزمون و بازخورد</b><p>۱۰ سؤال کوتاه با توضیح خطا، تلاش دوباره و مرور فاصله‌دار؛ پیشنهاد مرور در روزهای ۱، ۳ و ۷.</p></div></div>'+note('۲۵ دقیقه تمرکز، ۵ دقیقه استراحت','تایمر پیشنهادی باید مکث و پایان روشن داشته باشد. گذشت زمان یا تیک کار، اثبات حضور، فهمیدن یا مطالعه نیست؛ نتیجهٔ تمرین و بازخورد نیز به‌تنهایی تضمین یادگیری نیست.'),'آموزش آینده')

page(5,'ویدئو، کمک‌درس است','هدف، برگشت آسان از تماشا به فهمیدن و تمرین است.',badge('طرح آینده · همهٔ پخش‌ها UNVERIFIED')+diagram('video')+cards([('اختیاری و پیوسته','ویدئو داخل درس باز شود؛ تمام‌صفحه و بازگشت، جای درس و تمرین را حفظ کنند.'),('حقوق و منبع روشن','منبع، حق نمایش یا embed و نسخه/چاپ کتاب قبل از استفاده ثبت و بررسی شوند.'),('بازبینی واقعی','یک بازبین مناسب فیلم را کامل ببیند؛ تطابق درس، کیفیت توضیح و تجربهٔ دستگاه آزموده شود.')])+note('عدد واقعی امروز: صفر','طبق وضعیت ثبت‌شده، ویدئوی واقعی با بازبینی کامل و منتشرشده ۰ است. فهرست نامزدها به معنی تأیید یا انتشار نیست. پخش، تمام‌صفحه و بازگشت در Android، Safari و شبکهٔ ایران هنوز تأیید نشده‌اند.','warning'),'آموزش آینده')

page(6,'خانوادهٔ آنلاین؛ با مرز روشن','مقصد پیشنهادی: حساب مستقل والد و فرزند، همراه با توضیح قابل فهم برای کودک.',badge('ADR0015 هنوز PROPOSED؛ تأیید نشده')+diagram('family')+'<div class="two-col"><div class="card"><h3>گزارش آموزشی محدود</h3><p>فقط سرپرست فعال و مجاز: عنوان تکلیف، درس، موعد، وضعیت و زمان ثبت‌شده با منبع روشن؛ زمان آخرین دریافت هم دیده شود.</p></div><div class="card"><h3>شفافیت قبل از ثبت</h3><p>کودک بداند چه کسی کدام داده را می‌بیند. لغو سرپرستی و نشست، روی سرور و نمایش آفلاین اعمال شود.</p></div></div>'+note('حریم خصوصی پیش‌فرض عوض نمی‌شود','گفت‌وگوی خصوصی، یادداشت آزاد، سلامت و اطلاعات روانی خودکار وارد گزارش والد نمی‌شوند. مدیر خانواده بودن، مجوز دیدن همهٔ داده‌ها نیست.')+'<p>پذیرش لازم: یک فرزند و دو والد روی سه دستگاه، رد دسترسی فرد غیرمجاز، لغو مجوز، قطع/وصل اینترنت و نبود نمایش نادرست «زنده». نسخهٔ شخصی امروز این ارتباط را ندارد.</p>','هدف آنلاین · نیازمند تصمیم')

page(7,'رشد و مهارت زندگی','همراهی آرام برای زندگی روزمره، با انتخاب خود فرد.',badge('پیشنهاد آینده · AI و سلامت خاموش')+diagram('life')+cards([('برنامه برای همهٔ زندگی','یادگیری، مسئولیت خانه، پروژهٔ شخصی و عادت‌ها؛ پروفایل فرد از «دانش‌آموز» گسترده‌تر است.'),('خانوادهٔ پویا','اعضا و نقش‌ها می‌توانند تغییر کنند؛ محصول به یک خانواده یا یک سن ثابت وابسته نشود.'),('حمایت مسئولانه','ایده‌های رفاه و سلامت فقط پس از رضایت مناسب، سیاست روشن و بازبینی متخصص بررسی شوند.')])+note('این محصول جای پزشک یا درمانگر نیست','AI نباید نقش متخصص بالینی یا تشخیص پزشکی بگیرد. در این مسیر، قابلیت‌های AI و سلامت خاموش می‌مانند تا دامنه، رضایت، خطرها و بازبینی تخصصی جداگانه تأیید شوند.','warning'),'افق بلندتر')

page(8,'بازخورد، مسیر بهترشدن','مالک مسئلهٔ انتخاب‌شده را با رضایت می‌فرستد؛ تصمیم و انتشار انسانی می‌ماند.',badge('جریان پیشنهادی برای نسخه‌های بعد')+diagram('flow')+'<div class="steps"><div><b>انتخاب آگاهانه</b><p>فقط خلاصه یا نمونه‌ای که کاربر انتخاب کرده؛ امکان لغو رضایت و توقف استفادهٔ بعدی روشن باشد.</p></div><div><b>بررسی مسئله</b><p>خطا، پیشنهاد یا مسئلهٔ آموزشی دسته‌بندی شود؛ منبع، نسخه و معیار پذیرش مشخص باشند.</p></div><div><b>تصمیم و آزمون</b><p>انسان تغییر را بازبینی کند؛ اصلاح روی دادهٔ ساختگی آزموده و نسخهٔ مناسب برای تأیید آماده شود.</p></div><div><b>انتشار کنترل‌شده</b><p>پس از مجوز مرتبط، نسخهٔ تأییدشده ارائه شود؛ وضعیت و محدودیت‌ها به زبان روشن ثبت شوند.</p></div></div>'+note('مرز این چرخه','استخراج خودکار متن خصوصی، فرستادن خودکار به AI/عامل یا انتشار خودکار مجاز نیست. رضایت بازخورد از نقش مدیر خانواده جداست؛ این دفترچه هیچ جریان تازه‌ای را فعال نمی‌کند.'),'بازخورد و کنترل کیفیت')

page(9,'مسیر تحویل؛ بسته‌های ۱ تا ۳','برنامهٔ پیشنهادی با خروجی قابل بررسی؛ تاریخ و درصد ساختگی ندارد.',diagram('journey')+'<div class="packages"><div><span>۰۱</span><section><h2>قابلیت اتکای گوشی شخصی</h2><p><b>مالک اجرا:</b> توسعهٔ Android</p><p><b>خروج:</b> آزمون گوشی واقعی، خروجی/بازیابی، ارتقای با حفظ داده و کلید، تقویم جلالی و کنترل یادآوری؛ دادهٔ کاربر برای حل مشکل حذف نشود.</p></section></div><div><span>۰۲</span><section><h2>یکپارچه‌سازی کارهای موجود</h2><p><b>مالک اجرا:</b> مهندس یکپارچه‌سازی</p><p><b>خروج:</b> بررسی وابستگی PRها، مبنای migration قابل تکرار، آزمون مجوز و بازیابی روی یک نسخهٔ مشخص؛ بدون merge خودکار.</p></section></div><div><span>۰۳</span><section><h2>API واقعی و ورود والد</h2><p><b>مالک اجرا:</b> Backend/عملیات</p><p><b>خروج:</b> API و PostgreSQL واقعی، میزبانی PWA و ورود پیامکی والد با شواهد انتهابه‌انتها؛ انتخاب میزبان، هزینه، پیامک واقعی و deploy به مجوز مرتبط نیاز دارند.</p></section></div></div>','نقشهٔ اجرای پیشنهادی')

page(10,'مسیر تحویل؛ بسته‌های ۴ تا ۶','هر بسته بعد از خروج روشنِ وابستگی‌هایش تکمیل می‌شود.',badge('پیشنهاد برنامه؛ مجوز سیاست یا انتشار نیست')+'<div class="packages"><div><span>۰۴</span><section><h2>خانواده با مجوز تأییدشده</h2><p><b>مالک اجرا:</b> مهندس خانواده و مجوز</p><p><b>خروج:</b> تصمیم صریح ADR0015، شفافیت کودک، گزارش محدود؛ فرزند و دو والد روی سه دستگاه، لغو دسترسی و قطع/وصل اینترنت با کنترل سرور پذیرفته شوند.</p></section></div><div><span>۰۵</span><section><h2>یک درس هفتم، واقعاً کامل</h2><p><b>مالک اجرا:</b> مهندس آموزش</p><p><b>خروج:</b> هدف، توضیح، مثال، تمرین، آزمون ۱۰سؤالی، بازخورد و مرور؛ منبع/چاپ/حقوق محتوا و بازبینی متخصص ثبت شود، پخش اختیاری هم آزموده شود.</p></section></div><div><span>۰۶</span><section><h2>انتشار محدود و پایدار</h2><p><b>مالک اجرا:</b> QA/انتشار</p><p><b>خروج:</b> Android با کلید پایدار و PWA نصب‌پذیر iPhone، backup/خروجی/حذف روشن، پذیرش دستگاه واقعی و شبکهٔ ایران، راهنمای پشتیبانی و مجوز انتشار.</p></section></div></div>'+note('پایان یک بسته چه معنی دارد؟','خروجی باید وجود داشته باشد، روی نسخهٔ مشخص بررسی شود و محدودیتش ثبت شود. تست سبز بخشی از شواهد است؛ جای تجربهٔ کاربر روی محصول آنلاین را نمی‌گیرد.'),'نقشهٔ اجرای پیشنهادی')

page(11,'چرا تحویل طول کشید؟','توضیح صریح دربارهٔ ترتیب کار و فاصلهٔ کد تا استفاده.',cards([('دیر به مسیر کامل رسیدیم','مسیر «نصب کن و همان روز استفاده کن» دیر در اولویت قرار گرفت؛ بخش‌های زیاد، تجربهٔ کامل یک نفر را تضمین نکردند.'),('وابستگی اشتباه در تحویل','APK وابسته به سرور پیش از آماده‌شدن API تحویل شد و از مالک URL خواسته شد؛ آماده‌کردن نشانی درست، مسئولیت تیم فنی بود.'),('انباشت پیش از یکپارچه‌سازی','PRهای زنجیره‌ای و تغییرات زیرساخت طولانی شدند. CIهای موفق، قطعات را سنجیدند؛ محصول آنلاین خانواده هنوز به هم نرسید.')])+note('خرابی ابزار، علت اصلی نبود','خطای ابزار و کمبود دیسک زمان گرفتند، اما مسئلهٔ اصلی ترتیب تحویل و فاصلهٔ انتهابه‌انتها بود. تأخیر تقصیر کاربر نیست. عامل هم همیشه در پس‌زمینه فعال نیست و بین نوبت‌های اجرا ادامهٔ کار تضمین نمی‌شود.')+'<h2>هنوز باید حل شوند</h2><p>گوشی فیزیکی و Safari، شبکهٔ ایران، میزبان و SMS، کلید پایدار انتشار، بازبین آموزشی و سیاست‌های حریم خصوصی/رضایت. هیچ‌کدام با زیباترشدن دفترچه یا سبزشدن یک CI تمام نمی‌شوند.</p>','پاسخ‌گویی و یادگیری')

page(12,'هفتهٔ اول؛ از اعتماد شروع کنیم','پیشنهاد اجرا، نه تعهد تاریخ: روی گوشی واقعی، با دادهٔ ساختگی و بدون حذف دادهٔ قبلی.',badge('پیشنهاد نخستین هفته')+'<div class="week-plan"><div><b>شروع</b><p>نصب همان APK شخصی؛ ثبت نسخه و امضا، اجرای بدون URL، دو روز با دو ساعت متفاوت.</p></div><div><b>میانه</b><p>تیک، ویرایش، بایگانی و بستن/بازکردن؛ یادآوری، لغو قبل از موعد و خاموش‌کردن روی گوشی.</p></div><div><b>پایان</b><p>ثبت نتیجه و مسئله‌های واقعی؛ سپس خروجی/بازیابی و ارتقای امن را روی fixture جدا تکمیل و بررسی کنیم.</p></div></div>'+'<div class="finishlines"><section><span>خط پایان اول</span><h2>برنامهٔ شخصی قابل اتکا</h2><p>روی گوشی واقعی کار کند، داده بماند، یادآوری شفاف باشد و خروجی/بازیابی و ارتقا پذیرفته شوند.</p></section><section><span>خط پایان دوم</span><h2>خانواده و یادگیری آنلاین</h2><p>سه دستگاه با حساب مستقل و مجوز روشن، یک درس کامل و انتشار محدود Android/iPhone با شواهد واقعی.</p></section></div>'+note('قدم بعدی پس از این دفترچه','تثبیت برنامهٔ شخصی را شروع کنیم؛ نتیجهٔ هر بسته ثبت شود، بعد سراغ وابستگی بعد برویم. برای کارهای بدون مانع ادامه می‌دهیم و تصمیم‌های حریم خصوصی، زیرساخت و انتشار را جدا و مشخص برای تأیید آماده می‌کنیم.'),'شروع اجرایی پیشنهادی')

